class ReverseRange {
    int l, r, step;
public:
    ReverseRange(int l, int r, int step) : l(l), r(r), step(step) {}

    ReverseIterator begin() const {
        return ReverseIterator(r - step, step);
    }

    ReverseIterator end() const {
